def mark_existing_entries_validated(apps, schema_editor):
    # Patients who were already called/seen, and walk-ins registered at the desk, have effectively been validated.
    QueueEntry = apps.get_model('queue', 'QueueEntry')
    now = timezone.now()
    entries = QueueEntry.objects.filter(
        Q(status__in=['CALLED', 'CONSULTING', 'COMPLETED']) | Q(appointment__booking_type='WALK_IN')
    )
    for entry in entries:
        entry.validated_at = entry.arrival_time or entry.called_at or now
        entry.save(update_fields=['validated_at'])


